package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"unicode"
)

// ==================================================
// Phase A: 한글 MD 파일 수집 & 정제
// ==================================================

type MDCollector struct {
	filePaths []string
	totalSize int64
	texts     []string
}

// 한글 포함 여부 확인
func hasKorean(text string) bool {
	for _, ch := range text {
		if unicode.Is(unicode.Hangul_Syllables, ch) {
			return true
		}
	}
	return false
}

// 마크다운 태그 제거
func cleanMarkdown(content string) string {
	// # ## ### 제목 제거
	content = regexp.MustCompile(`^#+\s+.*$`).ReplaceAllString(content, "")

	// ``` 코드블록 제거
	content = regexp.MustCompile("```[\\s\\S]*?```").ReplaceAllString(content, "")

	// [링크](url) → 링크만 남기기
	content = regexp.MustCompile(`\[([^\]]+)\]\([^\)]+\)`).ReplaceAllString(content, "$1")

	// **굵은 텍스트** → 텍스트만 남기기
	content = regexp.MustCompile(`\*\*([^\*]+)\*\*`).ReplaceAllString(content, "$1")

	// *기울인 텍스트* → 텍스트만 남기기
	content = regexp.MustCompile(`\*([^\*]+)\*`).ReplaceAllString(content, "$1")

	// `코드` 제거
	content = regexp.MustCompile("`[^`]+`").ReplaceAllString(content, "")

	// HTML 태그 제거
	content = regexp.MustCompile(`<[^>]+>`).ReplaceAllString(content, "")

	// 여러 줄바꿈 → 단일 줄바꿈
	content = regexp.MustCompile(`\n{3,}`).ReplaceAllString(content, "\n\n")

	// 공백 정리
	content = strings.TrimSpace(content)

	return content
}

// 디렉토리 재귀 스캔
func (mc *MDCollector) scanDirectory(dir string) error {
	return filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil // 에러 무시하고 계속
		}

		if !info.IsDir() && strings.HasSuffix(path, ".md") {
			// 파일 크기 체크
			if info.Size() > 0 {
				mc.filePaths = append(mc.filePaths, path)
				mc.totalSize += info.Size()
			}
		}
		return nil
	})
}

// 한글 MD 파일만 수집
func (mc *MDCollector) collectKoreanMDs(dirs []string) error {
	var koreanFiles []string

	for _, dir := range dirs {
		_ = filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return nil
			}

			if !info.IsDir() && strings.HasSuffix(path, ".md") {
				// 파일 읽기 (처음 1000 바이트만 체크)
				file, err := os.Open(path)
				if err != nil {
					return nil
				}
				defer file.Close()

				buf := make([]byte, 1000)
				n, _ := file.Read(buf)
				if n > 0 && hasKorean(string(buf[:n])) {
					koreanFiles = append(koreanFiles, path)
				}
			}
			return nil
		})
	}

	mc.filePaths = koreanFiles
	fmt.Printf("✅ Found %d Korean MD files\n", len(koreanFiles))
	return nil
}

// 모든 파일 읽기 & 정제
func (mc *MDCollector) readAndClean() error {
	totalLines := 0

	for i, path := range mc.filePaths {
		file, err := os.Open(path)
		if err != nil {
			fmt.Printf("⚠️  Skip %s: %v\n", path, err)
			continue
		}
		defer file.Close()

		scanner := bufio.NewScanner(file)
		var fileText strings.Builder

		for scanner.Scan() {
			line := scanner.Text()
			if strings.TrimSpace(line) != "" {
				fileText.WriteString(line + "\n")
			}
		}

		content := fileText.String()
		cleaned := cleanMarkdown(content)

		if strings.TrimSpace(cleaned) != "" {
			mc.texts = append(mc.texts, cleaned)
			totalLines += len(strings.Split(cleaned, "\n"))
		}

		if (i+1)%100 == 0 {
			fmt.Printf("  Processed %d files...\n", i+1)
		}
	}

	fmt.Printf("✅ Total lines collected: %d\n", totalLines)
	return nil
}

// corpus.txt 저장
func (mc *MDCollector) save(outputPath string) error {
	file, err := os.Create(outputPath)
	if err != nil {
		return err
	}
	defer file.Close()

	writer := bufio.NewWriter(file)
	for _, text := range mc.texts {
		_, err := writer.WriteString(text + "\n\n")
		if err != nil {
			return err
		}
	}

	return writer.Flush()
}

// ==================================================
// MAIN
// ==================================================

func main() {
	fmt.Println("╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  FreeLang GPT - Phase A: Data Collection                ║")
	fmt.Println("║  MD 파일 수집 & 정제                                   ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝")

	home, _ := os.UserHomeDir()
	dirs := []string{
		filepath.Join(home, "projects"),
		filepath.Join(home, ".projects"),
	}

	collector := &MDCollector{}

	fmt.Println("\n[1/3] Scanning directories...")
	for _, dir := range dirs {
		if err := collector.scanDirectory(dir); err != nil {
			fmt.Printf("⚠️  Error scanning %s: %v\n", dir, err)
		}
	}
	fmt.Printf("✅ Found %d total MD files (%.1f MB)\n",
		len(collector.filePaths),
		float64(collector.totalSize)/(1024*1024))

	fmt.Println("\n[2/3] Filtering Korean MD files...")
	if err := collector.collectKoreanMDs(dirs); err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		os.Exit(1)
	}

	fmt.Println("\n[3/3] Reading & cleaning...")
	if err := collector.readAndClean(); err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		os.Exit(1)
	}

	outputPath := "data/corpus.txt"
	fmt.Printf("\n[4/4] Saving to %s...\n", outputPath)
	if err := collector.save(outputPath); err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		os.Exit(1)
	}

	// 통계
	fmt.Println("\n" + strings.Repeat("═", 60))
	fmt.Println("📊 COLLECTION SUMMARY")
	fmt.Println(strings.Repeat("═", 60))
	fmt.Printf("Total files collected:  %d\n", len(collector.filePaths))
	fmt.Printf("Total text blocks:      %d\n", len(collector.texts))
	fmt.Printf("Output file:            %s\n", outputPath)

	// 파일 크기 확인
	if info, err := os.Stat(outputPath); err == nil {
		fmt.Printf("Output size:            %.1f MB\n", float64(info.Size())/(1024*1024))
	}

	fmt.Println("\n✅ Phase A Complete!")
	fmt.Println("\nNext: go run data/tokenize.go")
}

