	for _, ch := range text {
		if id, ok := tk.charToID[ch]; ok {
			ids = append(ids, id)
		} else {
			ids = append(ids, 3) // <unk>
		}
	}
	return ids
}

// 데이터셋 생성
func (ds *Dataset) Create(tokenIds []int) {
	// 슬라이딩 윈도우로 시퀀스 쌍 생성
	for i := 0; i+SeqLen < len(tokenIds); i++ {
		seq := tokenIds[i : i+ContextLen]
		target := tokenIds[i+ContextLen]
		ds.sequences = append(ds.sequences, seq)
		ds.targets = append(ds.targets, target)
	}
