	if info, err := os.Stat("data/val.bin"); err == nil {
		fmt.Printf("Val file size:          %.1f MB\n", float64(info.Size())/(1024*1024))
	}

	fmt.Println("\n✅ Phase C Complete!")
	fmt.Println("\nNext: go run train/main.go")
}

