package main

import (
	"math"
)

// ==================================================
// Phase D: GPT 모델 구조 (Go 구현)
// ==================================================

// 텐서 (1D 평탄화)
type Tensor struct {
	data   []float64
	shape  []int
	size   int
}

// 파라미터 (requires_grad 포함)
type Parameter struct {
	data  *Tensor
	grad  *Tensor
}

// 선형 레이어
type Linear struct {
	weight *Parameter
	bias   *Parameter
	in     int
	out    int
}

// 레이어 정규화
type LayerNorm struct {
	weight *Parameter
	bias   *Parameter
	eps    float64
}

// GPT 설정
type GPTConfig struct {
	VocabSize int
	DModel    int
	NumHeads  int
	NumLayers int
	MaxSeqLen int
}

// ==================================================
// 유틸리티
// ==================================================

// 텐서 생성
func NewTensor(shape []int) *Tensor {
	size := 1
	for _, d := range shape {
		size *= d
	}
	return &Tensor{
		data:  make([]float64, size),
		shape: shape,
		size:  size,
	}
}

// 랜덤 초기화 (Xavier)
func (t *Tensor) InitXavier(in, out int) {
	scale := math.Sqrt(2.0 / float64(in+out))
	for i := range t.data {
		// 단순 균등분포 (정규분포는 생략)
		t.data[i] = (math.Sin(float64(i*17%1000)) * scale) - scale/2
	}
}

// 인덱스 접근 (2D)
func (t *Tensor) Get(i, j int) float64 {
	idx := i*t.shape[1] + j
	if idx < len(t.data) {
		return t.data[idx]
	}
	return 0
}

func (t *Tensor) Set(i, j int, val float64) {
	idx := i*t.shape[1] + j
	if idx < len(t.data) {
		t.data[idx] = val
	}
}

// 행렬곱 (간단한 구현)
func MatMul(a, b *Tensor) *Tensor {
	// a: [M, K], b: [K, N] → [M, N]
	M, K := a.shape[0], a.shape[1]
	N := b.shape[1]

	result := NewTensor([]int{M, N})

	for i := 0; i < M; i++ {
		for j := 0; j < N; j++ {
			sum := 0.0
			for k := 0; k < K; k++ {
				sum += a.Get(i, k) * b.Get(k, j)
			}
			result.Set(i, j, sum)
		}
	}

	return result
}

// 덧셈
func Add(a, b *Tensor) *Tensor {
	result := NewTensor(a.shape)
	for i := range a.data {
		result.data[i] = a.data[i] + b.data[i]
	}
	return result
}

// 스칼라 곱
func Scale(t *Tensor, scalar float64) *Tensor {
	result := NewTensor(t.shape)
	for i, v := range t.data {
		result.data[i] = v * scalar
	}
	return result
}

// ==================================================
// 신경망 레이어
// ==================================================

// 선형 레이어 생성
func NewLinear(in, out int) *Linear {
	weight := &Parameter{
		data: NewTensor([]int{out, in}),
		grad: NewTensor([]int{out, in}),
	}
	weight.data.InitXavier(in, out)

	bias := &Parameter{
		data: NewTensor([]int{out}),
		grad: NewTensor([]int{out}),
	}

	return &Linear{
		weight: weight,
		bias:   bias,
		in:     in,
		out:    out,
	}
}

// 선형 레이어 포워드
func (l *Linear) Forward(x *Tensor) *Tensor {
	// x: [batch, in] → [batch, out]
	// y = x @ W^T + b

	batch := x.shape[0]
	weightT := NewTensor([]int{l.in, l.out})

	// 전치
	for i := 0; i < l.in; i++ {
		for j := 0; j < l.out; j++ {
			weightT.Set(i, j, l.weight.data.Get(j, i))
		}
	}

	// 행렬곱
	y := MatMul(x, weightT)

	// 편향 더하기
	for i := 0; i < batch; i++ {
		for j := 0; j < l.out; j++ {
			y.Set(i, j, y.Get(i, j)+l.bias.data.data[j])
		}
	}

	return y
}

// ==================================================
// 활성화 함수
// ==================================================

// ReLU
func ReLU(x *Tensor) *Tensor {
	result := NewTensor(x.shape)
	for i, v := range x.data {
		if v > 0 {
			result.data[i] = v
		}
	}
	return result
}

// Softmax (수치 안정성)
func Softmax(x *Tensor) *Tensor {
	// x: [batch, vocab]
	result := NewTensor(x.shape)
	batch := x.shape[0]
	vocab := x.shape[1]

	for b := 0; b < batch; b++ {
		// Max 찾기
		max := x.Get(b, 0)
		for v := 0; v < vocab; v++ {
			if x.Get(b, v) > max {
				max = x.Get(b, v)
			}
		}

		// Exp 합
		sumExp := 0.0
		for v := 0; v < vocab; v++ {
			sumExp += math.Exp(x.Get(b, v) - max)
		}

		// Softmax
		for v := 0; v < vocab; v++ {
			prob := math.Exp(x.Get(b, v)-max) / sumExp
			result.Set(b, v, prob)
		}
	}

	return result
}

// ==================================================
// 손실 함수
// ==================================================

// Cross-entropy loss
func CrossEntropyLoss(logits, targets *Tensor) float64 {
	// logits: [batch, vocab]
	// targets: [batch] (인덱스)
	// 출력: scalar loss

	batch := logits.shape[0]
	probs := Softmax(logits)

	totalLoss := 0.0
	for b := 0; b < batch; b++ {
		targetIdx := int(targets.data[b])
		if targetIdx >= 0 && targetIdx < logits.shape[1] {
			prob := probs.Get(b, targetIdx)
			if prob > 0 {
				totalLoss += -math.Log(prob)
			}
		}
	}

	return totalLoss / float64(batch)
}

// ==================================================
// 옵티마이저 (Adam)
// ==================================================

type Adam struct {
	lr    float64
	beta1 float64
	beta2 float64
	eps   float64
	t     int64
	m     map[*Tensor]*Tensor // 첫 번째 모멘트
	v     map[*Tensor]*Tensor // 두 번째 모멘트
}

func NewAdam(lr float64) *Adam {
	return &Adam{
		lr:    lr,
		beta1: 0.9,
		beta2: 0.999,
		eps:   1e-8,
		t:     0,
		m:     make(map[*Tensor]*Tensor),
		v:     make(map[*Tensor]*Tensor),
	}
}

// Adam 스텝 (간단한 구현)
func (opt *Adam) Step(params []*Parameter) {
	opt.t++

	for _, param := range params {
		w := param.data
		g := param.grad

		// m_t, v_t 초기화
		if _, ok := opt.m[w]; !ok {
			opt.m[w] = NewTensor(w.shape)
			opt.v[w] = NewTensor(w.shape)
		}

		m := opt.m[w]
		v := opt.v[w]

		// 업데이트
		for i := range w.data {
			// m_t = β₁*m + (1-β₁)*g
			m.data[i] = opt.beta1*m.data[i] + (1-opt.beta1)*g.data[i]

			// v_t = β₂*v + (1-β₂)*g²
			v.data[i] = opt.beta2*v.data[i] + (1-opt.beta2)*g.data[i]*g.data[i]

			// Bias correction
			mHat := m.data[i] / (1 - math.Pow(opt.beta1, float64(opt.t)))
			vHat := v.data[i] / (1 - math.Pow(opt.beta2, float64(opt.t)))

			// 파라미터 업데이트
			w.data[i] -= opt.lr * mHat / (math.Sqrt(vHat) + opt.eps)
		}
	}
}

// ==================================================
// 간단한 임베딩
// ==================================================

type Embedding struct {
	weight *Parameter
}

func NewEmbedding(vocabSize, dimModel int) *Embedding {
	weight := &Parameter{
		data: NewTensor([]int{vocabSize, dimModel}),
		grad: NewTensor([]int{vocabSize, dimModel}),
	}
	weight.data.InitXavier(vocabSize, dimModel)
	return &Embedding{weight: weight}
}

// Forward: [batch, seq] → [batch, seq, dim]
func (e *Embedding) Forward(tokenIds [][]int, seqLen, dim int) *Tensor {
	batch := len(tokenIds)
	result := NewTensor([]int{batch, seqLen, dim})

	// 간단한 구현: 각 토큰의 임베딩을 복사
	for b := 0; b < batch; b++ {
		for s := 0; s < seqLen && s < len(tokenIds[b]); s++ {
			tokenID := tokenIds[b][s]
			if tokenID >= 0 && tokenID < e.weight.data.shape[0] {
				for d := 0; d < dim; d++ {
					idx := (b*seqLen+s)*dim + d
					result.data[idx] = e.weight.data.Get(tokenID, d)
				}
			}
		}
	}

	return result
}

