package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
	"time"
)

// ==================================================
// Phase D: 학습 드라이버
// ==================================================

// 배치 로드
func LoadBatch(filename string, startIdx, batchSize int) ([][]int, []int, error) {
	file, err := os.Open(filename)
	if err != nil {
		return nil, nil, err
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	var seqs [][]int
	var targets []int

	lineIdx := 0
	// 첫 번째 줄은 헤더 (개수)
	if scanner.Scan() {
		lineIdx++
	}

	// 시작 인덱스까지 스킵
	for i := 0; i < startIdx && scanner.Scan(); i++ {
		lineIdx++
	}

	// 배치 로드
	for len(seqs) < batchSize && scanner.Scan() {
		line := scanner.Text()
		parts := strings.Split(line, "\t")
		if len(parts) != 2 {
			continue
		}

		// 시퀀스 파싱
		seqStr := strings.TrimSpace(parts[0])
		seqParts := strings.Fields(seqStr)
		var seq []int
		for _, p := range seqParts {
			if id, err := strconv.Atoi(p); err == nil {
				seq = append(seq, id)
			}
		}

		// 타겟 파싱
		targetStr := strings.TrimSpace(parts[1])
		target, _ := strconv.Atoi(targetStr)

		if len(seq) > 0 {
			seqs = append(seqs, seq)
			targets = append(targets, target)
		}
	}

	return seqs, targets, nil
}

// 토큰 ID를 텐서로 변환
func TokensToTensor(tokenIds [][]int) *Tensor {
	batch := len(tokenIds)
	seqLen := 0
	if batch > 0 {
		seqLen = len(tokenIds[0])
	}

	t := NewTensor([]int{batch, seqLen})
	for i, seq := range tokenIds {
		for j, id := range seq {
			if j < seqLen {
				t.Set(i, j, float64(id))
			}
		}
	}
	return t
}

// 타겟을 텐서로 변환
func TargetsToTensor(targets []int) *Tensor {
	t := NewTensor([]int{len(targets)})
	for i, target := range targets {
		t.data[i] = float64(target)
	}
	return t
}

// ==================================================
// MAIN
// ==================================================

func main() {
	fmt.Println("╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  FreeLang GPT - Phase D: Training                      ║")
	fmt.Println("║  Character-level Language Model Training               ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝")

	// 설정
	config := GPTConfig{
		VocabSize: 11267,
		DModel:    128,
		NumHeads:  4,
		NumLayers: 4,
		MaxSeqLen: 128,
	}

	batchSize := 32
	epochs := 2  // 짧은 테스트용
	lr := 1e-3

	fmt.Printf("\n[CONFIG]\n")
