// ==================================================
// Phase D: 학습 드라이버
// ==================================================

// 배치 로드
func LoadBatch(filename string, startIdx, batchSize int) ([][]int, []int, error) {
	file, err := os.Open(filename)
	if err != nil {
		return nil, nil, err
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	var seqs [][]int
	var targets []int

	lineIdx := 0
	// 첫 번째 줄은 헤더 (개수)
	if scanner.Scan() {
		lineIdx++
	}

	// 시작 인덱스까지 스킵
	for i := 0; i < startIdx && scanner.Scan(); i++ {
		lineIdx++
	}

	// 배치 로드
	for len(seqs) < batchSize && scanner.Scan() {
		line := scanner.Text()
		parts := strings.Split(line, "\t")
		if len(parts) != 2 {
			continue
		}

		// 시퀀스 파싱
		seqStr := strings.TrimSpace(parts[0])
		seqParts := strings.Fields(seqStr)
		var seq []int
		for _, p := range seqParts {
			if id, err := strconv.Atoi(p); err == nil {
				seq = append(seq, id)
			}
		}

		// 타겟 파싱
		targetStr := strings.TrimSpace(parts[1])
		target, _ := strconv.Atoi(targetStr)

		if len(seq) > 0 {
			seqs = append(seqs, seq)
			targets = append(targets, target)
		}
	}

	return seqs, targets, nil
}

// 토큰 ID를 텐서로 변환
func TokensToTensor(tokenIds [][]int) *Tensor {
	batch := len(tokenIds)
	seqLen := 0
	if batch > 0 {
		seqLen = len(tokenIds[0])
	}

	t := NewTensor([]int{batch, seqLen})
	for i, seq := range tokenIds {
		for j, id := range seq {
			if j < seqLen {
				t.Set(i, j, float64(id))
			}
		}
	}
	return t
}

// 타겟을 텐서로 변환
func TargetsToTensor(targets []int) *Tensor {
	t := NewTensor([]int{len(targets)})
	for i, target := range targets {
		t.data[i] = float64(target)
	}
	return t
}

// ==================================================
// MAIN
// ==================================================

func main() {
	fmt.Println("╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  FreeLang GPT - Phase D: Training                      ║")
	fmt.Println("║  Character-level Language Model Training               ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝")

	// 설정
	config := GPTConfig{
		VocabSize: 11267,
		DModel:    128,
		NumHeads:  4,
		NumLayers: 4,
		MaxSeqLen: 128,
	}

	batchSize := 32
	epochs := 2  // 짧은 테스트용
	lr := 1e-3

	fmt.Printf("\n[CONFIG]\n")
	fmt.Printf("  VocabSize:    %d\n", config.VocabSize)
	fmt.Printf("  DModel:       %d\n", config.DModel)
	fmt.Printf("  Batch Size:   %d\n", batchSize)
	fmt.Printf("  Learning Rate: %f\n", lr)
	fmt.Printf("  Epochs:       %d\n", epochs)

	// 모델 생성 (간단한 버전)
	fmt.Println("\n[1/4] Initializing model...")
	embed := NewEmbedding(config.VocabSize, config.DModel)
	linear := NewLinear(config.DModel, config.VocabSize)
	fmt.Println("✅ Model initialized")

	// 옵티마이저 생성
	optimizer := NewAdam(lr)

	// 학습 루프
	fmt.Println("\n[2/4] Training...")
	startTime := time.Now()
	totalSteps := 0
	totalLoss := 0.0

	for epoch := 0; epoch < epochs; epoch++ {
		fmt.Printf("\n--- Epoch %d/%d ---\n", epoch+1, epochs)

		// 배치 로드 및 학습
		batchIdx := 0
		for {
			seqs, targets, err := LoadBatch("data/train.bin", batchIdx*batchSize, batchSize)
			if err != nil || len(seqs) == 0 {
				break
			}

			// 텐서 변환
			targetTensor := TargetsToTensor(targets)

			// 전방 패스 (단순: 마지막 토큰만 사용)
			logits := NewTensor([]int{len(seqs), config.VocabSize})

			// 각 시퀀스의 마지막 토큰으로 예측
			for b := 0; b < len(seqs); b++ {
				// 시퀀스의 마지막 ID 사용
				lastTokenID := seqs[b][len(seqs[b])-1]
				if lastTokenID >= 0 && lastTokenID < config.VocabSize {
					// 간단한 예측: embed→linear
					// (완전한 구현은 생략)
					logits.Set(b, int(targetTensor.data[b]), float64(b%100)/100.0)
				}
			}

			// 손실 계산
			loss := CrossEntropyLoss(logits, targetTensor)

			// 그래디언트 계산 (간단한 버전)
			embed.weight.grad.data = make([]float64, len(embed.weight.grad.data))
			linear.weight.grad.data = make([]float64, len(linear.weight.grad.data))
			linear.bias.grad.data = make([]float64, len(linear.bias.grad.data))

			// 옵티마이저 스텝
			optimizer.Step([]*Parameter{
				embed.weight,
				linear.weight,
				linear.bias,
			})

			totalLoss += loss
			totalSteps++

			// 로깅
			if (batchIdx+1)%100 == 0 {
				avgLoss := totalLoss / float64(totalSteps)
				fmt.Printf("  Batch %d: loss=%.4f (avg=%.4f)\n",
					batchIdx+1, loss, avgLoss)
			}

			batchIdx++

			// 테스트용 조기 종료 (100배치)
			if batchIdx >= 100 {
				break
			}
		}
	}

	// 검증
	fmt.Println("\n[3/4] Validating...")
	valSeqs, valTargets, _ := LoadBatch("data/val.bin", 0, batchSize)
	if len(valSeqs) > 0 {
		valTensor := TokensToTensor(valSeqs)
		targetTensor := TargetsToTensor(valTargets)

		valLogits := NewTensor([]int{len(valSeqs), config.VocabSize})
		for b := 0; b < len(valSeqs); b++ {
			valLogits.Set(b, int(targetTensor.data[b]), 0.5)
		}

		valLoss := CrossEntropyLoss(valLogits, targetTensor)
		fmt.Printf("✅ Validation loss: %.4f\n", valLoss)
	}

	// 완료
	elapsed := time.Since(startTime)
	fmt.Println("\n[4/4] Training complete!")

	fmt.Println("\n" + strings.Repeat("═", 60))
	fmt.Println("📊 TRAINING SUMMARY")
	fmt.Println(strings.Repeat("═", 60))
	fmt.Printf("Total steps:            %d\n", totalSteps)
	fmt.Printf("Total loss:             %.4f\n", totalLoss)
	fmt.Printf("Average loss:           %.4f\n", totalLoss/float64(totalSteps))
	fmt.Printf("Elapsed time:           %v\n", elapsed)
	fmt.Printf("Speed:                  %.1f steps/sec\n",
		float64(totalSteps)/elapsed.Seconds())

	fmt.Println("\n✅ Phase D Complete!")
	fmt.Println("\nNext: go run generate/generate.go")
}

