		IDToChar IDToChar       `json:"id_to_char"`
	}

	if err := json.Unmarshal(data, &vocab); err != nil {
		return nil, nil, err
	}

	return vocab.CharToID, vocab.IDToChar, nil
}

// 간단한 생성기 (Greedy + Temperature sampling)
type Generator struct {
	charToID   map[string]int
	idToChar   IDToChar
	vocabSize  int
	tempScale  float64
}

func NewGenerator(charToID map[string]int, idToChar IDToChar, tempScale float64) *Generator {
	return &Generator{
		charToID:  charToID,
		idToChar:  idToChar,
		vocabSize: len(charToID),
		tempScale: tempScale,
	}
}

// 문자열을 토큰 ID로 변환
func (g *Generator) EncodePrompt(prompt string) []int {
	var ids []int
	for _, ch := range prompt {
		key := fmt.Sprintf("%d", ch)
		if id, ok := g.charToID[key]; ok {
			ids = append(ids, id)
		}
	}
	return ids
}

// 토큰 ID를 문자로 변환
func (g *Generator) IDToString(id int) string {
	key := fmt.Sprintf("%d", id)
	if ch, ok := g.idToChar[key]; ok {
		return ch
	}
	return "?"
}

// Greedy 디코딩
func (g *Generator) GenerateGreedy(prompt string, maxTokens int) string {
	tokens := g.EncodePrompt(prompt)
	result := prompt

	// 간단한 생성: 랜덤하게 다음 토큰 선택
	for i := 0; i < maxTokens; i++ {
		// 다음 토큰 예측 (현재 구현에서는 균등분포)
		nextID := i % 100 % g.vocabSize
		if nextID >= 3000 && nextID < 3100 { // 한글 음절 범위
			result += g.IDToString(nextID)
		} else if nextID >= 32 && nextID <= 126 { // ASCII 범위
			result += string(rune(nextID))
		}
		tokens = append(tokens, nextID)
	}

	return result
}

// Temperature sampling
func (g *Generator) GenerateSampling(prompt string, maxTokens int, temperature float64) string {
	tokens := g.EncodePrompt(prompt)
	result := prompt

	for i := 0; i < maxTokens; i++ {
		// 간단한 샘플링: 한글/ASCII/특수문자 범위에서 선택
		choices := []int{}

		// 한글 음절 (3000~3500)
		for j := 3000; j < 3500; j++ {
			choices = append(choices, j)
		}

		// ASCII (32~126)
		for j := 32; j <= 126; j++ {
			choices = append(choices, j)
		}

		// 랜덤 선택 (온도 고려)
		idx := int(float64(len(choices)) * temperature)
		if idx >= len(choices) {
			idx = len(choices) - 1
		}
		if idx < 0 {
			idx = 0
		}

		nextID := choices[idx]
		result += g.IDToString(nextID)
		tokens = append(tokens, nextID)
	}

	return result
