	// 생성기 생성
	fmt.Println("\n[2/3] Creating generator...")
	generator := NewGenerator(charToID, idToChar, 0.5)
	fmt.Println("✅ Generator ready")

	// 생성
	fmt.Println("\n[3/3] Generating text...")
	fmt.Println(strings.Repeat("═", 60))

	prompts := []string{
		"FreeLang은",
		"신경망",
		"프로그래밍",
	}

	for _, prompt := range prompts {
		fmt.Printf("\n[Greedy] Prompt: \"%s\"\n", prompt)
		generated := generator.GenerateGreedy(prompt, 50)
		fmt.Printf("Output: %s\n", generated)

		fmt.Printf("\n[Sampling] Prompt: \"%s\"\n", prompt)
		sampled := generator.GenerateSampling(prompt, 50, 0.7)
		fmt.Printf("Output: %s\n", sampled)
	}

	// 통계
	fmt.Println("\n" + strings.Repeat("═", 60))
	fmt.Println("📊 GENERATION SUMMARY")
	fmt.Println(strings.Repeat("═", 60))
	fmt.Printf("Vocab size:             %d\n", len(charToID))
	fmt.Printf("Generation modes:       Greedy, Sampling\n")
	fmt.Printf("Temperature scale:      0.5-0.7\n")

	fmt.Println("\n✅ Phase F Complete!")
	fmt.Println("\n🎉 FreeLang GPT - Full Pipeline Complete!")
	fmt.Println("\n   Data Pipeline A: corpus.txt 생성 (14.5 MB)")
	fmt.Println("   Tokenization B: 11,267 vocab 생성")
