		if idx >= len(choices) {
			idx = len(choices) - 1
		}
		if idx < 0 {
			idx = 0
		}

		nextID := choices[idx]
		result += g.IDToString(nextID)
		tokens = append(tokens, nextID)
	}

	return result
}

