package main

import (
	"math"
)

// ==================================================
// Transformer-based GPT Model (간단한 버전)
// ==================================================

// Attention 헤드
type AttentionHead struct {
	qProj *Linear
	kProj *Linear
	vProj *Linear
	scale float64
}

func NewAttentionHead(dModel, dHead int) *AttentionHead {
	return &AttentionHead{
		qProj: NewLinear(dModel, dHead),
		kProj: NewLinear(dModel, dHead),
		vProj: NewLinear(dModel, dHead),
		scale: 1.0 / math.Sqrt(float64(dHead)),
	}
}

// Scaled Dot-Product Attention
func (ah *AttentionHead) Forward(x *Tensor) *Tensor {
	// x: [batch, seq, d_model]
	// 출력: [batch, seq, d_head]

	batch := x.shape[0]
	seqLen := x.shape[1]
	dModel := x.shape[2]
	dHead := ah.qProj.out

	// Q, K, V 생성
	q := ah.qProj.Forward(x)  // [batch, seq, d_head]
	k := ah.kProj.Forward(x)  // [batch, seq, d_head]
	v := ah.vProj.Forward(x)  // [batch, seq, d_head]

	// Attention scores: Q @ K^T / sqrt(d_head)
	scores := NewTensor([]int{batch, seqLen, seqLen})

	for b := 0; b < batch; b++ {
		for i := 0; i < seqLen; i++ {
			for j := 0; j < seqLen; j++ {
				// Causal mask: i < j인 경우 -inf
				if i < j {
					scores.Set(b, i, j, -1e9)
					continue
				}

				// Q[i] @ K[j]^T
				score := 0.0
				for d := 0; d < dHead; d++ {
					qIdx := (b*seqLen+i)*dHead + d
					kIdx := (b*seqLen+j)*dHead + d
					if qIdx < len(q.data) && kIdx < len(k.data) {
						score += q.data[qIdx] * k.data[kIdx]
					}
				}
				scores.Set(b, i, j, score*ah.scale)
			}
		}
	}

	// Softmax
	attnWeights := NewTensor([]int{batch, seqLen, seqLen})
	for b := 0; b < batch; b++ {
		for i := 0; i < seqLen; i++ {
			// Max 찾기
			max := scores.Get(b, i, 0)
			for j := 0; j < seqLen; j++ {
				if scores.Get(b, i, j) > max {
					max = scores.Get(b, i, j)
				}
			}

			// Softmax
			sumExp := 0.0
			for j := 0; j < seqLen; j++ {
				sumExp += math.Exp(scores.Get(b, i, j) - max)
			}

			for j := 0; j < seqLen; j++ {
				prob := math.Exp(scores.Get(b, i, j)-max) / sumExp
				attnWeights.Set(b, i, j, prob)
			}
		}
	}

	// 출력: Attention weights @ V
	output := NewTensor([]int{batch, seqLen, dHead})

	for b := 0; b < batch; b++ {
		for i := 0; i < seqLen; i++ {
			for d := 0; d < dHead; d++ {
				val := 0.0
				for j := 0; j < seqLen; j++ {
					weight := attnWeights.Get(b, i, j)
					vIdx := (b*seqLen+j)*dHead + d
					if vIdx < len(v.data) {
						val += weight * v.data[vIdx]
					}
				}
				output.Set(b, i, d, val)
			}
		}
	}

	return output
}

// Multi-Head Attention
type MultiHeadAttention struct {
	heads    []*AttentionHead
	outProj  *Linear
	numHeads int
	dModel   int
	dHead    int
}

func NewMultiHeadAttention(dModel, numHeads int) *MultiHeadAttention {
	dHead := dModel / numHeads

	var heads []*AttentionHead
	for i := 0; i < numHeads; i++ {
		heads = append(heads, NewAttentionHead(dModel, dHead))
	}

	return &MultiHeadAttention{
		heads:    heads,
		outProj:  NewLinear(dModel, dModel),
		numHeads: numHeads,
		dModel:   dModel,
		dHead:    dHead,
	}
}

// Multi-Head 포워드
func (mha *MultiHeadAttention) Forward(x *Tensor) *Tensor {
	// x: [batch, seq, d_model]
	// 출력: [batch, seq, d_model]

	batch := x.shape[0]
	seqLen := x.shape[1]

	// 각 헤드 실행
	var headOutputs []*Tensor
	for _, head := range mha.heads {
		out := head.Forward(x)
		headOutputs = append(headOutputs, out)
	}

	// 헤드 병합: [batch, seq, d_model]
	merged := NewTensor([]int{batch, seqLen, mha.dModel})

	for b := 0; b < batch; b++ {
		for s := 0; s < seqLen; s++ {
			for h := 0; h < mha.numHeads; h++ {
				for d := 0; d < mha.dHead; d++ {
					headOut := headOutputs[h]
					// 리니어 인덱싱으로 접근 (3D → 1D)
					srcIdx := (b*seqLen+s)*mha.dHead + d
					dstIdx := (b*seqLen+s)*mha.dModel + h*mha.dHead + d
					if srcIdx < len(headOut.data) && dstIdx < len(merged.data) {
						merged.data[dstIdx] = headOut.data[srcIdx]
					}
				}
			}
		}
	}

	// 출력 투영
	output := mha.outProj.Forward(merged)
	return output
}

// Feed-Forward Network
type FFN struct {
	fc1 *Linear // d_model → 4*d_model
	fc2 *Linear // 4*d_model → d_model
}

func NewFFN(dModel int) *FFN {
	return &FFN{
		fc1: NewLinear(dModel, 4*dModel),
		fc2: NewLinear(4*dModel, dModel),
	}
}

func (ffn *FFN) Forward(x *Tensor) *Tensor {
	// hidden = GELU(x @ fc1)
	hidden := ffn.fc1.Forward(x)
	hidden = ReLU(hidden) // 간단히 ReLU 사용

	// output = hidden @ fc2
	output := ffn.fc2.Forward(hidden)
	return output
}

// Transformer Block (Pre-LN)
type TransformerBlock struct {
	attn      *MultiHeadAttention
	ffn       *FFN
	lnAttn    *LayerNorm
	lnFFN     *LayerNorm
}

func NewTransformerBlock(dModel, numHeads int) *TransformerBlock {
	return &TransformerBlock{
		attn:   NewMultiHeadAttention(dModel, numHeads),
		ffn:    NewFFN(dModel),
		lnAttn: &LayerNorm{eps: 1e-6},
		lnFFN:  &LayerNorm{eps: 1e-6},
	}
}

// Pre-LN Transformer Block 포워드
func (tb *TransformerBlock) Forward(x *Tensor) *Tensor {
	// Attention branch: x + MHA(LN(x))
	x1 := x // Residual

	// 정규화 (간단히 스킵)
	attnOut := tb.attn.Forward(x)
	x = Add(x1, attnOut) // Residual connection

	// FFN branch: x + FFN(LN(x))
	x2 := x // Residual
	ffnOut := tb.ffn.Forward(x)
	x = Add(x2, ffnOut) // Residual connection

	return x
}

// 완전한 GPT 모델
type GPTModelFull struct {
	embed   *Embedding
	blocks  []*TransformerBlock
	lmHead  *Linear
	config  GPTConfig
}

func NewGPTModelFull(config GPTConfig) *GPTModelFull {
	embed := NewEmbedding(config.VocabSize, config.DModel)

	var blocks []*TransformerBlock
	for i := 0; i < config.NumLayers; i++ {
		blocks = append(blocks, NewTransformerBlock(config.DModel, config.NumHeads))
	}

	return &GPTModelFull{
		embed:  embed,
		blocks: blocks,
		lmHead: NewLinear(config.DModel, config.VocabSize),
		config: config,
	}
}

// Forward pass
func (gpt *GPTModelFull) Forward(tokenIds [][]int) *Tensor {
	// tokenIds: [batch, seq]
	// 출력: [batch, seq, vocab]

	seqLen := 0
	if len(tokenIds) > 0 {
		seqLen = len(tokenIds[0])
	}

	// 임베딩
	x := gpt.embed.Forward(tokenIds, seqLen, gpt.config.DModel)

	// Transformer 블록 스택
	for _, block := range gpt.blocks {
		x = block.Forward(x)
	}

	// LM Head: [batch, seq, vocab_size]
	logits := gpt.lmHead.Forward(x)

	return logits
}

