package main

import (
	"fmt"
	"strings"
	"time"
)

// ==================================================
// Transformer GPT 학습 스크립트
// ==================================================

func main() {
	fmt.Println("╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  FreeLang GPT - Transformer Training                   ║")
	fmt.Println("║  Multi-Head Attention + Feed-Forward                   ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝")

	// 설정
	config := GPTConfig{
		VocabSize: 11267,
		DModel:    128,
		NumHeads:  4,
		NumLayers: 2, // 2개 블록 (가벼움)
		MaxSeqLen: 128,
	}

	batchSize := 16 // 메모리 절약
	epochs := 1     // 1 epoch만 (데모)
	lr := 5e-4      // 낮은 학습률

	fmt.Printf("\n[CONFIG]\n")
	fmt.Printf("  Model Type:   Transformer GPT\n")
	fmt.Printf("  VocabSize:    %d\n", config.VocabSize)
	fmt.Printf("  DModel:       %d\n", config.DModel)
	fmt.Printf("  NumHeads:     %d\n", config.NumHeads)
	fmt.Printf("  NumLayers:    %d\n", config.NumLayers)
	fmt.Printf("  Batch Size:   %d\n", batchSize)
	fmt.Printf("  Learning Rate: %f\n", lr)

	// 모델 초기화
	fmt.Println("\n[1/4] Initializing Transformer GPT...")
	startTime := time.Now()
	gpt := NewGPTModelFull(config)
	fmt.Printf("✅ Model initialized (%.2fs)\n", time.Since(startTime).Seconds())

	// 파라미터 수 계산
	paramCount := 0
	paramCount += config.VocabSize * config.DModel // 임베딩
	paramCount += config.NumLayers * (
		config.DModel * config.DModel * 4 + // Attention (Q,K,V,O)
			config.DModel * 4 * config.DModel * 2) // FFN
	paramCount += config.DModel * config.VocabSize // LM Head

	fmt.Printf("  Parameters:   ~%dM\n", paramCount/1000000)

	// 옵티마이저
	optimizer := NewAdam(lr)

	// 학습 루프
	fmt.Println("\n[2/4] Training...")
	totalSteps := 0
	totalLoss := 0.0
	bestLoss := 1e9

	for epoch := 0; epoch < epochs; epoch++ {
		fmt.Printf("\n--- Epoch %d/%d ---\n", epoch+1, epochs)

		batchIdx := 0
		epochLoss := 0.0

		for {
			// 배치 로드
			seqs, targets, err := LoadBatch("data/train.bin", batchIdx*batchSize, batchSize)
			if err != nil || len(seqs) == 0 {
				break
			}

			// Forward pass
			logits := gpt.Forward(seqs)
			targetTensor := TargetsToTensor(targets)

			// Loss 계산
			loss := CrossEntropyLoss(logits, targetTensor)

			// Backward pass (간단한 버전 - 실제 그래디언트는 계산 안 함)
