func main() {
	fmt.Println("╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  FreeLang GPT - Phase G: REST API Server               ║")
	fmt.Println("║  Web Service & HTTP Interface                          ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝")

	// Vocab 로드 (간단한 버전)
	charToID = make(map[string]int)
	idToChar = make(map[string]string)
	models = make(map[string]*ModelInfo)

	// 더미 vocab 초기화 (실제로는 vocab.json 로드)
	for i := 0; i < 100; i++ {
		key := fmt.Sprintf("%d", i)
		charToID[key] = i
		idToChar[key] = string(rune(i))
	}

	fmt.Println("\n[1/2] Initializing API...")
	fmt.Printf("✅ Vocab size: %d\n", len(charToID))

	// 라우팅 설정
	fmt.Println("\n[2/2] Setting up routes...")
	setupRoutes()

	// 서버 시작
	port := ":8080"
	fmt.Printf("\n🚀 Server starting on http://localhost:8080\n")
	fmt.Printf("\n📚 Documentation: http://localhost:8080/docs\n")
	fmt.Printf("💚 Health check: http://localhost:8080/health\n")

	fmt.Println("\n" + strings.Repeat("═", 60))

	if err := http.ListenAndServe(port, nil); err != nil {
		fmt.Printf("❌ Server error: %v\n", err)
	}
}

